{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C13"],
      "claim": "In fasting healthy volunteers, thalidomide absolute oral bioavailability was 80–100% at 100 mg, showing that a lipophilic, poorly water-soluble aromatic dicarbonyl can be well absorbed; this supports high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C19"],
      "claim": "Sertraline, which shares the chlorophenyl-cyclohexane lipophilic motif, has an absolute oral bioavailability of 80–95% in humans, supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "Zilascorb tablets had an absolute bioavailability of 34±13% in patients, a moderate F above the 20% threshold, supporting high for a lipophilic, poorly soluble neutral molecule.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "Tiludronate had an absolute oral bioavailability of 6% (2–11%) in healthy volunteers, an affirmative low-F result, but its bisphosphonate polarity and poor permeability are not transferable to the lipophilic neutral naphthoquinone query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a lipophilic, poorly water-soluble neutral naphthoquinone. The most relevant supportive evidence comes from lipophilic/chlorophenyl-cyclohexane and poorly soluble molecules with high oral bioavailability, while the affirmative low-F evidence comes from polar bisphosphonates or structurally dissimilar compounds with low transferability. Therefore F >= 20% is better supported.",
  "evidence_gaps": [
    "No direct absolute bioavailability measurement for the query in the retrieved evidence; all analogues have low Morgan similarity (<0.27).",
    "The query condition is fasted, but most supporting records are not explicitly fasted or use different formulations and doses.",
    "The query's absolute F is likely borderline near the 20% threshold and may be formulation- and food-dependent."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

